// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzz: amount to deposit (as uint256) and a boolean deciding whether the callee should revert
    function testFuzz_property(uint256 amount, bool calleeReverts) public {
        // keep amount in a reasonable range to avoid overflow in test harness operations
        amount = bound(amount, 1, 1 ether);

        // deploy a helper that can be toggled to revert on receive
        ReverterOrRecorder helper = new ReverterOrRecorder();
        helper.setShouldRevert(calleeReverts);

        // fund the helper so it can receive (not necessary but safe)
        vm.deal(address(this), 2 ether);

        // actor will be the helper's address; we need to have the helper be the caller of withdrawBalance
        // but withdrawBalance sends to msg.sender, so we should have deposited into c from the helper
        // To deposit from the helper, we need the helper to call addToBalance payable.

        // Give the helper some ETH and make it call c.addToBalance{value: amount}()
        vm.deal(address(helper), amount);
        // instruct the helper to deposit
        helper.depositTo(address(c), amount);

        // Sanity: helper's recorded deposited amount equals amount
        assertEq(c.getBalance(address(helper)), amount);

        // Now, helper will call c.withdrawBalance() which will attempt a low-level call back to the helper
        // The difference: reference reverts when the low-level call returns false, mutant does not.
        bool ok;
        // perform the withdraw as if helper is calling
        vm.prank(address(helper));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertTrue): If the helper's receive() reverts, then the reference must revert the withdraw call.
        // We observe that by checking: when calleeReverts == true, the call must not succeed (ok == false).
        // This holds for the reference implementation for all inputs; the mutant (which ignores the returned success flag)
        // will allow ok == true for some inputs when the low-level call fails.
        if (calleeReverts) {
            assertTrue(!ok);
        } else {
            // when helper does not revert, withdraw should succeed
            assertTrue(ok);
        }
    }
}

// Adversarial helper: can be commanded to revert on receive, and can call addToBalance()/withdrawBalance()
contract ReverterOrRecorder {
    bool public shouldRevert;
    Reentrance public lastC;

    function setShouldRevert(bool v) external {
        shouldRevert = v;
    }

    // deposit into target contract by calling addToBalance payable
    function depositTo(address target, uint256 amt) external {
        lastC = Reentrance(target);
        // call addToBalance payable from this contract
        (bool s, ) = address(target).call{value: amt}(abi.encodeWithSignature("addToBalance()"));
        require(s, "deposit failed");
    }

    // allow receiving funds; optionally revert to simulate failing recipient
    receive() external payable {
        if (shouldRevert) revert("reverting on receive");
    }
}
